def maxPathSum(root):
    best = float('-inf')
    def g(n):
        nonlocal best
        if not n:
            return 0
        l = max(0, g(n.left))
        r = max(0, g(n.right))
        best = max(best, n.val + l + r)
        return n.val + max(l, r)
    g(root)
    return best

