def maxPathSum(root):
    nodes = []
    q = [root]
    for n in q:
        nodes.append(n)
        for c in (n.left, n.right):
            if c:
                q.append(c)
    idx = {id(n): i for i, n in enumerate(nodes)}
    adj = [[] for _ in nodes]
    for n in nodes:
        for c in (n.left, n.right):
            if c:
                adj[idx[id(n)]].append(idx[id(c)])
                adj[idx[id(c)]].append(idx[id(n)])
    best = float('-inf')
    def dfs(u, seen, s):
        nonlocal best
        best = max(best, s)
        for v in adj[u]:
            if v not in seen:
                dfs(v, seen | {v}, s + nodes[v].val)
    for i in range(len(nodes)):
        dfs(i, {i}, nodes[i].val)
    return best

