"""Random tree generators (level-order lists with None), shared by problem definitions.
The whole file is also embedded in large-test generator code via inspect.getsource."""
import random


def _ser(vals, left, right):
    out, q, qi = [], [0], 0
    while qi < len(q):
        i = q[qi]; qi += 1
        if i is None:
            out.append(None); continue
        out.append(vals[i]); q.append(left[i]); q.append(right[i])
    while out and out[-1] is None:
        out.pop()
    return out


def rand_tree(r, n, lo=-5, hi=9):
    if n == 0:
        return []
    vals = [r.randint(lo, hi) for _ in range(n)]
    left, right = [None] * n, [None] * n
    free = [(0, 'l'), (0, 'r')]
    for i in range(1, n):
        p, side = free.pop(r.randrange(len(free)))
        if side == 'l':
            left[p] = i
        else:
            right[p] = i
        free += [(i, 'l'), (i, 'r')]
    return _ser(vals, left, right)


def rand_bst(r, n, lo=0, hi=20):
    if n == 0:
        return []
    keys = r.sample(range(lo, hi), n)
    vals, left, right = [], [], []
    for k in keys:
        vals.append(k); left.append(None); right.append(None)
        if len(vals) == 1:
            continue
        cur = 0
        while True:
            if k < vals[cur]:
                if left[cur] is None:
                    left[cur] = len(vals) - 1; break
                cur = left[cur]
            else:
                if right[cur] is None:
                    right[cur] = len(vals) - 1; break
                cur = right[cur]
    return _ser(vals, left, right)


def perfect_tree(r, depth, lo=0, hi=9):
    return [r.randint(lo, hi) for _ in range(2 ** depth - 1)]

def gen():
    r = random.Random(4)
    return [rand_tree(r, 60000, -50, 50)]

